// Host tests for Infratic-lib. Compares library output with vectors
// generated by @solana/web3.js (see js/gen.mjs). Build + run: ./build.sh
#include <Arduino.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
#include <fstream>
#include <sstream>
#include <map>
#include "Infratic-lib.h"
#include <mbedtls/base64.h>

#ifndef INFRATIC_VERSION
Infratic solana("https://mock.rpc"); // old lib needs this global
#endif

static int g_pass = 0, g_fail = 0;
static std::map<std::string, std::pair<int, int>> g_groups;
static std::string g_group;

#define CHECK(cond, what)                                                         \
    do {                                                                          \
        if (cond) { g_pass++; g_groups[g_group].first++; }                        \
        else { g_fail++; g_groups[g_group].second++;                              \
               if (g_groups[g_group].second <= 3)                                 \
                   printf("  FAIL [%s] %s\n", g_group.c_str(), std::string(what).c_str()); } \
    } while (0)

static std::vector<uint8_t> fromHex(const std::string &h) {
    std::vector<uint8_t> v;
    for (size_t i = 0; i + 1 < h.size(); i += 2) v.push_back((uint8_t)strtol(h.substr(i, 2).c_str(), nullptr, 16));
    return v;
}
static std::string toHex(const std::vector<uint8_t> &v) {
    static const char *d = "0123456789abcdef";
    std::string s;
    for (uint8_t b : v) { s += d[b >> 4]; s += d[b & 15]; }
    return s;
}
static std::vector<uint8_t> b58(const String &s) {
    uint8_t buf[128]; size_t len = sizeof(buf);
    if (!base58Decode(s, buf, len)) return {};
    return std::vector<uint8_t>(buf, buf + len);
}

static void testPda(Infratic &sol, JsonArray cases) {
    g_group = "pda";
    for (JsonObject c : cases) {
        std::vector<std::vector<uint8_t>> seeds;
        for (JsonVariant s : c["seeds"].as<JsonArray>()) seeds.push_back(fromHex(s.as<std::string>()));
        String pda; uint8_t bump = 0;
        bool ok = sol.derivePDA(seeds, c["program"].as<const char *>(), pda, bump);
        std::string label = c["name"] | c["pda"].as<std::string>();
        CHECK(ok && pda == c["pda"].as<const char *>() && bump == c["bump"].as<int>(),
              label + " expected " + c["pda"].as<std::string>() + "/" + std::to_string(c["bump"].as<int>()) +
              " got " + pda.s + "/" + std::to_string(bump));
    }
}

