static void testEncoders() {
    g_group = "encoders";
    CHECK(toHex(encodeU64BE(0x0102030405060708ULL)) == "0102030405060708", "u64 be");
    CHECK(toHex(encodeU64LE(0x0102030405060708ULL)) == "0807060504030201", "u64 le");
    CHECK(toHex(encodeU32LE(0x01020304)) == "04030201", "u32 le");
    CHECK(toHex(encodeI64LE(-2)) == "feffffffffffffff", "i64 le");
    std::vector<uint8_t> v;
    appendCompactU16(v, 0); appendCompactU16(v, 127); appendCompactU16(v, 128); appendCompactU16(v, 300); appendCompactU16(v, 16384);
    CHECK(toHex(v) == "007f8001ac02808001", "compact-u16 " + toHex(v));
    std::vector<uint8_t> s;
    appendBorshString(s, "abc");
    CHECK(toHex(s) == "03000000616263", "borsh string");
}
#endif

// Decodes a legacy message into an order-independent form so that our
// output can be compared with web3.js (which sorts keys inside each group).
struct DecodedMsg
{
    bool ok = false;
    int header[3] = {0, 0, 0};
    std::vector<std::string> keys;
    std::string payer, blockhash, canon;
};

static size_t readCompact(const std::vector<uint8_t> &b, size_t &o)
{
    size_t v = 0, shift = 0;
    while (o < b.size()) { uint8_t x = b[o++]; v |= (size_t)(x & 0x7f) << shift; if (!(x & 0x80)) break; shift += 7; }
    return v;
}

static DecodedMsg decodeMsg(const std::vector<uint8_t> &m)
{
    DecodedMsg d;
    if (m.size() < 4) return d;
    size_t o = 0;
    for (int i = 0; i < 3; i++) d.header[i] = m[o++];
    size_t nk = readCompact(m, o);
    for (size_t i = 0; i < nk; i++) { d.keys.push_back(toHex(std::vector<uint8_t>(m.begin() + o, m.begin() + o + 32))); o += 32; }
    d.blockhash = toHex(std::vector<uint8_t>(m.begin() + o, m.begin() + o + 32)); o += 32;
    auto flags = [&](size_t i) {
        bool signer = i < (size_t)d.header[0];
        bool writable = signer ? i < (size_t)(d.header[0] - d.header[1]) : i < nk - d.header[2];
        return std::string(signer ? "S" : "-") + (writable ? "W" : "R");
    };
    std::map<std::string, std::string> keyFlags;
    for (size_t i = 0; i < nk; i++) keyFlags[d.keys[i]] = flags(i);
    for (auto &kv : keyFlags) d.canon += kv.first.substr(0, 8) + ":" + kv.second + " ";
    d.canon += "| " + d.blockhash.substr(0, 8) + " |";
    size_t ni = readCompact(m, o);
    for (size_t i = 0; i < ni; i++)
    {
        size_t prog = m[o++];
        d.canon += " ix " + d.keys[prog].substr(0, 8) + " [";
        size_t na = readCompact(m, o);
        for (size_t j = 0; j < na; j++) d.canon += d.keys[m[o++]].substr(0, 8) + ",";
        size_t nd = readCompact(m, o);
        d.canon += "] " + toHex(std::vector<uint8_t>(m.begin() + o, m.begin() + o + nd));
        o += nd;
    }
    d.payer = d.keys.empty() ? "" : d.keys[0];
    d.ok = (o == m.size());
    return d;
}

static void testTx(JsonArray cases)
{
    g_group = "tx";
    for (JsonObject c : cases)
    {
        std::string name = c["name"].as<std::string>();
        Transaction tx;
        std::vector<Keypair> signers;
        for (JsonVariant s : c["signers"].as<JsonArray>())
        {
            std::vector<uint8_t> sk = b58(s.as<const char *>());
            signers.push_back(Keypair::fromPrivateKey(sk.data()));
        }
        tx.fee_payer = signers[0].pubkey();
        tx.recent_blockhash = c["blockhash"].as<const char *>();
        for (JsonObject ix : c["instructions"].as<JsonArray>())
        {
            std::vector<AccountMeta> metas;
            for (JsonObject a : ix["accounts"].as<JsonArray>())
                metas.push_back(AccountMeta{Pubkey::fromBase58(a["key"].as<const char *>()), a["signer"].as<bool>(), a["writable"].as<bool>()});
            tx.add(Instruction(Pubkey::fromBase58(ix["program"].as<const char *>()), metas, fromHex(ix["data"].as<std::string>())));
        }

        std::vector<uint8_t> ours = tx.serializeMessage();
        DecodedMsg a = decodeMsg(ours), b = decodeMsg(fromHex(c["message"].as<std::string>()));
        CHECK(a.ok, name + " message parses");
        CHECK(a.header[0] == b.header[0] && a.header[1] == b.header[1] && a.header[2] == b.header[2],
              name + " header " + std::to_string(a.header[0]) + std::to_string(a.header[1]) + std::to_string(a.header[2]) +
              " want " + std::to_string(b.header[0]) + std::to_string(b.header[1]) + std::to_string(b.header[2]));
        CHECK(a.payer == b.payer, name + " fee payer first");
        CHECK(a.canon == b.canon, name + " accounts/instructions\n    want " + b.canon + "\n    got  " + a.canon);

        tx.sign(signers);
        std::string b64 = tx.serializeBase64().s;
        CHECK(!b64.empty(), name + " serialize");
        // signatures must be valid ed25519 signatures of OUR message by the key at that index
        bool sigsOk = (int)tx.signatures.size() == a.header[0];
        for (size_t i = 0; sigsOk && i < tx.signatures.size(); i++)
            sigsOk = Ed25519::verify(tx.signatures[i].data(), fromHex(a.keys[i]).data(), ours.data(), ours.size());
        CHECK(sigsOk, name + " signatures verify");
        // when key order happens to match web3.js the bytes must be identical
        if (toHex(ours) == c["message"].as<std::string>())
            CHECK(b64 == c["tx"].as<std::string>(), name + " identical signed tx");
    }
}

static void testSendSol(Infratic &sol, JsonObject c) {
    g_group = "sendSol";
    std::string sent;
    std::string bh = c["blockhash"].as<std::string>();
    g_httpHandler = [&](const std::string &, const std::string &body) -> MockHttpResponse {
        if (body.find("getLatestBlockhash") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"context\":{\"slot\":1},\"value\":{\"blockhash\":\"" + bh + "\",\"lastValidBlockHeight\":100}}}"};
        if (body.find("sendTransaction") != std::string::npos) {
            DynamicJsonDocument d(4096); deserializeJson(d, body);
            sent = d["params"][0].as<std::string>();
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":\"5sig\"}"};
        }
        if (body.find("getSignatureStatuses") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"context\":{\"slot\":1},\"value\":[{\"confirmationStatus\":\"confirmed\",\"err\":null}]}}"};
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":null}"};
    };
    sol.sendSol(c["secret"].as<const char *>(), c["from"].as<const char *>(), c["to"].as<const char *>(), c["lamports"].as<uint64_t>());
    CHECK(sent == c["tx"].as<std::string>(), "sendSol tx bytes\n    want " + c["tx"].as<std::string>().substr(0, 60) + "\n    got  " + sent.substr(0, 60));
}

static void testEscrowDecode(Infratic &sol, JsonArray cases) {
    g_group = "escrowDecode";
    sol.setEscrowProgramId("3kk7vGfWwT7Uq7M6uV5cfSyXodbsr7Py6gmBYDCMvstQ");
    for (JsonObject c : cases) {
        std::string data = c["data"].as<std::string>();
        g_httpHandler = [&](const std::string &, const std::string &) -> MockHttpResponse {
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"context\":{\"slot\":1},\"value\":{\"data\":[\"" + data +
                             "\",\"base64\"],\"executable\":false,\"lamports\":1,\"owner\":\"3kk7vGfWwT7Uq7M6uV5cfSyXodbsr7Py6gmBYDCMvstQ\",\"rentEpoch\":0}}}"};
        };
        EscrowAccountResult r = sol.getEscrowAccount("11111111111111111111111111111111");
        std::string id = c["orderId"].as<std::string>();
        const EscrowAccount &a = r.account;
        CHECK(r.success, id + " success");
        CHECK(a.buyer == c["buyer"].as<const char *>() && a.seller == c["seller"].as<const char *>(), id + " keys");
        CHECK(a.amount == c["amount"].as<uint64_t>(), id + " amount");
        CHECK(a.orderId == id.c_str(), id + " orderId got '" + a.orderId.s + "'");
        CHECK((int)a.status == c["status"].as<int>(), id + " status got " + std::to_string((int)a.status));
        CHECK(a.createdAt == c["createdAt"].as<int64_t>() && a.expiresAt == c["expiresAt"].as<int64_t>(), id + " times");
        CHECK(a.bump == c["bump"].as<int>() && a.deliveryConfirmed == c["deliveryConfirmed"].as<bool>() &&
                  a.disputeInitiated == c["disputeInitiated"].as<bool>(), id + " flags");
        CHECK(a.proofHash == c["proofHash"].as<const char *>(), id + " proofHash");
    }
#ifdef INFRATIC_VERSION
    // corrupted length prefix must be rejected, not read out of bounds
    g_httpHandler = [&](const std::string &, const std::string &) -> MockHttpResponse {
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"data\":[\"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA/////w==\",\"base64\"],\"owner\":\"3kk7vGfWwT7Uq7M6uV5cfSyXodbsr7Py6gmBYDCMvstQ\"}}}"};
    };
    CHECK(!sol.getEscrowAccount("11111111111111111111111111111111").success, "corrupt data rejected");
    // wrong owner must be rejected
    std::string data0 = cases[0]["data"].as<std::string>();
    g_httpHandler = [&](const std::string &, const std::string &) -> MockHttpResponse {
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"data\":[\"" + data0 + "\",\"base64\"],\"owner\":\"11111111111111111111111111111111\"}}}"};
    };
    CHECK(!sol.getEscrowAccount("11111111111111111111111111111111").success, "wrong owner rejected");
    // escrow PDA derivation matches web3.js
    String pda; uint8_t bump = 0;
    CHECK(sol.deriveEscrowPDA(cases[0]["pdaOrderId"].as<const char *>(), cases[0]["pdaBuyer"].as<const char *>(), pda, bump) &&
          pda == cases[0]["pda"].as<const char *>() && bump == cases[0]["pdaBump"].as<int>(), "deriveEscrowPDA " + pda.s);
#endif
}

#ifdef INFRATIC_VERSION
static void testEscrowCreate(Infratic &sol, JsonObject c)
{
    g_group = "escrowCreate";
    std::string sent, bh = c["blockhash"].as<std::string>();
    g_httpHandler = [&](const std::string &, const std::string &body) -> MockHttpResponse {
        auto has = [&](const char *m) { return body.find(m) != std::string::npos; };
        if (has("getMinimumBalanceForRentExemption")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":2978880}"};
        if (has("getBalance")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"context\":{\"slot\":1},\"value\":900000000}}"};
        if (has("getLatestBlockhash")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"blockhash\":\"" + bh + "\",\"lastValidBlockHeight\":1}}}"};
        if (has("sendTransaction")) {
            DynamicJsonDocument d(8192); deserializeJson(d, body); sent = d["params"][0].as<std::string>();
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":\"5sig\"}"};
        }
        if (has("getSignatureStatuses")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":[{\"confirmationStatus\":\"confirmed\",\"err\":null}]}}"};
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":null}"};
    };
    sol.setEscrowProgramId("3kk7vGfWwT7Uq7M6uV5cfSyXodbsr7Py6gmBYDCMvstQ");
    EscrowCreateResult r = sol.escrow_create(c["secret"].as<const char *>(), c["buyer"].as<const char *>(), c["seller"].as<const char *>(),
                                             c["amount"].as<uint64_t>(), c["orderId"].as<const char *>(), c["exp"].as<int64_t>());
    CHECK(r.success && r.escrowPDA == c["pda"].as<const char *>(), "result " + r.errorMessage.s + " pda " + r.escrowPDA.s);
    std::vector<uint8_t> raw;
    { size_t n = 0; raw.resize(sent.size()); mbedtls_base64_decode(raw.data(), raw.size(), &n, (const unsigned char *)sent.data(), sent.size()); raw.resize(n); }
    CHECK(raw.size() > 65 && raw[0] == 1, "one signature");
    std::vector<uint8_t> msg(raw.begin() + std::min<size_t>(65, raw.size()), raw.end());
    DecodedMsg a = decodeMsg(msg), b = decodeMsg(fromHex(c["message"].as<std::string>()));
    CHECK(a.ok && a.canon == b.canon, "escrow_create instruction\n    want " + b.canon + "\n    got  " + a.canon);
    CHECK(raw.size() > 65 && Ed25519::verify(raw.data() + 1, fromHex(a.keys[0]).data(), msg.data(), msg.size()), "signature");

    // order_id longer than a PDA seed must be rejected before sending
    CHECK(!sol.escrow_create(c["secret"].as<const char *>(), c["buyer"].as<const char *>(), c["seller"].as<const char *>(),
                             1, String("x").s.append(40, 'y').c_str(), 10).success, "long order_id rejected");
}

static void testSpl(Infratic &sol, JsonObject spl)
{
    g_group = "spl";
    for (JsonObject c : spl["ata"].as<JsonArray>())
    {
        String ata;
        CHECK(sol.getAssociatedTokenAddress(c["owner"].as<const char *>(), c["mint"].as<const char *>(), ata,
                                            c["program"].as<const char *>()) && ata == c["ata"].as<const char *>(),
              "ATA " + ata.s + " want " + c["ata"].as<std::string>());
    }
    for (JsonObject c : spl["send"].as<JsonArray>())
    {
        std::string sent, bh = c["blockhash"].as<std::string>(), name = std::string("sendSplToken ") + (c["createAta"].as<bool>() ? "+ata " : "") + c["program"].as<std::string>().substr(0, 6);
        bool askedDecimals = false;
        g_httpHandler = [&](const std::string &, const std::string &body) -> MockHttpResponse {
            auto has = [&](const char *m) { return body.find(m) != std::string::npos; };
            if (has("getTokenSupply")) { askedDecimals = true; return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"amount\":\"1\",\"decimals\":6,\"uiAmount\":1}}}"}; }
            if (has("getLatestBlockhash")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"blockhash\":\"" + bh + "\",\"lastValidBlockHeight\":1000}}}"};
            if (has("sendTransaction")) { DynamicJsonDocument d(8192); deserializeJson(d, body); sent = d["params"][0].as<std::string>(); return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":\"5sig\"}"}; }
            if (has("getSignatureStatuses")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":[{\"confirmationStatus\":\"confirmed\",\"err\":null}]}}"};
            if (has("getBlockHeight")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":10}"};
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":null}"};
        };
        String sig;
        // second variant reads decimals from chain
        int decimals = c["createAta"].as<bool>() ? c["decimals"].as<int>() : -1;
        bool ok = sol.sendSplToken(c["secret"].as<const char *>(), c["from"].as<const char *>(), c["to"].as<const char *>(),
                                   c["mint"].as<const char *>(), std::stoull(c["amount"].as<std::string>()), sig, decimals,
                                   c["createAta"].as<bool>(), c["program"].as<const char *>());
        CHECK(ok, name + " result");
        CHECK(askedDecimals == (decimals < 0), name + " decimals lookup");
        std::vector<uint8_t> raw(sent.size()); size_t n = 0;
        mbedtls_base64_decode(raw.data(), raw.size(), &n, (const unsigned char *)sent.data(), sent.size()); raw.resize(n);
        CHECK(raw.size() > 65 && raw[0] == 1, name + " one signature");
        if (raw.size() <= 65) continue;
        std::vector<uint8_t> msg(raw.begin() + 65, raw.end());
        DecodedMsg a = decodeMsg(msg), b = decodeMsg(fromHex(c["message"].as<std::string>()));
        CHECK(a.ok && a.canon == b.canon && a.header[0] == b.header[0] && a.header[1] == b.header[1] && a.header[2] == b.header[2],
              name + " message\n    want " + b.canon + "\n    got  " + a.canon);
        CHECK(Ed25519::verify(raw.data() + 1, fromHex(a.keys[0]).data(), msg.data(), msg.size()), name + " signature");
    }
}

static void testComputeBudget(Infratic &sol, JsonObject c)
{
    g_group = "computeBudget";
    Instruction lim = Infratic::setComputeUnitLimitIx(200000), pr = Infratic::setComputeUnitPriceIx(25000);
    CHECK(toHex(lim.data) == c["limitData"].as<std::string>() && toHex(pr.data) == c["priceData"].as<std::string>(), "ix data");
    CHECK(base58Encode(lim.programId.data.data(), 32) == c["program"].as<const char *>(), "program id");

    // sendSol with a priority fee must match web3.js byte for byte
    JsonObject t = c["send"];
    std::string sent, bh = t["blockhash"].as<std::string>();
    g_httpHandler = [&](const std::string &, const std::string &body) -> MockHttpResponse {
        if (body.find("getLatestBlockhash") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"blockhash\":\"" + bh + "\",\"lastValidBlockHeight\":100}}}"};
        if (body.find("sendTransaction") != std::string::npos) {
            DynamicJsonDocument d(4096); deserializeJson(d, body); sent = d["params"][0].as<std::string>();
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":\"5sig\"}"};
        }
        if (body.find("getSignatureStatuses") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":[{\"confirmationStatus\":\"confirmed\",\"err\":null}]}}"};
        if (body.find("getRecentPrioritizationFees") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":[{\"slot\":1,\"prioritizationFee\":0},{\"slot\":2,\"prioritizationFee\":500},{\"slot\":3,\"prioritizationFee\":100},{\"slot\":4,\"prioritizationFee\":9000},{\"slot\":5,\"prioritizationFee\":200}]}"};
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":null}"};
    };
    sol.setPriorityFee(25000, 200000);
    sol.sendSol(t["secret"].as<const char *>(), t["from"].as<const char *>(), t["to"].as<const char *>(), t["lamports"].as<uint64_t>());
    {
        auto decodeTx = [](const std::string &b64) {
            std::vector<uint8_t> raw(b64.size()); size_t n = 0;
            mbedtls_base64_decode(raw.data(), raw.size(), &n, (const unsigned char *)b64.data(), b64.size()); raw.resize(n);
            return raw;
        };
        std::vector<uint8_t> ours = decodeTx(sent), want = decodeTx(t["tx"].as<std::string>());
        CHECK(ours.size() > 65 && ours.size() == want.size(), "sendSol with priority fee size");
        if (ours.size() > 65)
        {
            std::vector<uint8_t> m1(ours.begin() + 65, ours.end()), m2(want.begin() + 65, want.end());
            DecodedMsg a = decodeMsg(m1), b = decodeMsg(m2);
            CHECK(a.ok && a.canon == b.canon, "sendSol with priority fee message\n    want " + b.canon + "\n    got  " + a.canon);
            CHECK(Ed25519::verify(ours.data() + 1, fromHex(a.keys[0]).data(), m1.data(), m1.size()), "sendSol with priority fee signature");
        }
    }

    // a tx that already has a compute budget is left alone
    Transaction tx;
    tx.add(Infratic::setComputeUnitPriceIx(1));
    sol.applyPriorityFee(tx);
    CHECK(tx.instructions.size() == 1, "existing budget kept");
    sol.setPriorityFee(0, 0);
    Transaction tx2;
    sol.applyPriorityFee(tx2);
    CHECK(tx2.instructions.empty(), "fee off");

    uint64_t fee = 0;
    CHECK(sol.estimatePriorityFee({"So11111111111111111111111111111111111111112"}, fee, 75) && fee == 500, "estimate p75 " + std::to_string(fee));
    CHECK(sol.estimatePriorityFee({}, fee, 100) && fee == 9000, "estimate max");
}

static void testNonce(Infratic &sol, JsonObject c)
{
    g_group = "nonce";
    for (JsonObject f : c["fromSeed"].as<JsonArray>())
    {
        std::vector<uint8_t> seed = fromHex(f["seed"].as<std::string>());
        Keypair k = Keypair::fromSeed(seed.data());
        CHECK(k.publicBase58() == f["pub"].as<const char *>(), "fromSeed " + k.publicBase58().s);
        CHECK(Keypair::fromBase58(k.secretBase58()).publicBase58() == k.publicBase58(), "secretBase58 round trip");
    }
    Keypair g1 = Keypair::generate(), g2 = Keypair::generate();
    uint8_t gsig[64]; const uint8_t m[3] = {1, 2, 3};
    Ed25519::sign(gsig, g1.privkey.data(), g1.privkey.data() + 32, m, 3);
    CHECK(g1.publicBase58() != g2.publicBase58() && Ed25519::verify(gsig, g1.pubkey().data.data(), m, 3), "generate");

    JsonObject cr = c["create"], acc = c["account"];
    std::string sent, bh = cr["blockhash"].as<std::string>(), accData = acc["data"].as<std::string>();
    g_httpHandler = [&](const std::string &, const std::string &body) -> MockHttpResponse {
        auto has = [&](const char *x) { return body.find(x) != std::string::npos; };
        if (has("getMinimumBalanceForRentExemption")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":" + std::to_string(cr["rent"].as<uint64_t>()) + "}"};
        if (has("getLatestBlockhash")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"blockhash\":\"" + bh + "\",\"lastValidBlockHeight\":1000}}}"};
        if (has("getAccountInfo")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":{\"data\":[\"" + accData + "\",\"base64\"],\"owner\":\"11111111111111111111111111111111\",\"lamports\":1447680}}}"};
        if (has("sendTransaction")) { DynamicJsonDocument d(8192); deserializeJson(d, body); sent = d["params"][0].as<std::string>(); return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":\"5sig\"}"}; }
        if (has("getSignatureStatuses")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"value\":[{\"confirmationStatus\":\"confirmed\",\"err\":null}]}}"};
        if (has("getBlockHeight")) return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":10}"};
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":null}"};
    };
    auto decodeSent = [&](int nsig, std::vector<uint8_t> &msg) {
        std::vector<uint8_t> raw(sent.size()); size_t n = 0;
        mbedtls_base64_decode(raw.data(), raw.size(), &n, (const unsigned char *)sent.data(), sent.size()); raw.resize(n);
        if (raw.size() < (size_t)(1 + 64 * nsig) || raw[0] != nsig) return std::vector<uint8_t>();
        msg.assign(raw.begin() + 1 + 64 * nsig, raw.end());
        return raw;
    };

    String sig;
    Keypair nonceKp = Keypair::fromBase58(cr["nonce"].as<const char *>());
    CHECK(sol.createNonceAccount(cr["payer"].as<const char *>(), nonceKp, cr["authority"].as<const char *>(), sig), "createNonceAccount");
    std::vector<uint8_t> msg, raw = decodeSent(2, msg);
    DecodedMsg a = decodeMsg(msg), b = decodeMsg(fromHex(cr["message"].as<std::string>()));
    CHECK(!raw.empty() && a.ok && a.canon == b.canon, "create message\n    want " + b.canon + "\n    got  " + a.canon);
    bool sigsOk = !raw.empty();
    for (int i = 0; sigsOk && i < 2; i++) sigsOk = Ed25519::verify(raw.data() + 1 + 64 * i, fromHex(a.keys[i]).data(), msg.data(), msg.size());
    CHECK(sigsOk, "create: both signatures valid");

    NonceInfo info;
    CHECK(sol.getNonce(acc["address"].as<const char *>(), info) && info.nonce == acc["nonce"].as<const char *>() &&
          info.authority == acc["authority"].as<const char *>() && info.lamportsPerSignature == 5000, "getNonce");

    // durable transfer: advance first, then compute budget, then transfer
    JsonObject d = c["durable"];
    Keypair dev = Keypair::fromBase58(d["secret"].as<const char *>());
    Transaction tx;
    tx.fee_payer = dev.pubkey();
    std::vector<uint8_t> data = encodeU32LE(2), lam = encodeU64LE(d["lamports"].as<uint64_t>());
    data.insert(data.end(), lam.begin(), lam.end());
    tx.add(Instruction(Pubkey::fromBase58("11111111111111111111111111111111"),
                       {AccountMeta::writable(dev.pubkey(), true), AccountMeta::writable(Pubkey::fromBase58(d["to"].as<const char *>()), false)}, data));
    CHECK(sol.useDurableNonce(tx, acc["address"].as<const char *>(), dev.publicBase58()), "useDurableNonce");
    sol.setPriorityFee(1000);
    sent.clear();
    CHECK(sol.signAndSend(tx, {dev}, sig), "signAndSend durable");
    sol.setPriorityFee(0);
    raw = decodeSent(1, msg);
    a = decodeMsg(msg); b = decodeMsg(fromHex(d["message"].as<std::string>()));
    CHECK(!raw.empty() && a.ok && a.canon == b.canon, "durable message\n    want " + b.canon + "\n    got  " + a.canon);
    CHECK(tx.recent_blockhash == acc["nonce"].as<const char *>(), "nonce used as blockhash");
}

static void testRpcHelpers(Infratic &sol) {
    g_group = "rpc";
    std::string lastBody;
    g_httpHandler = [&](const std::string &, const std::string &body) -> MockHttpResponse {
        lastBody = body;
        if (body.find("getMinimumBalanceForRentExemption") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":2978880}"};
        if (body.find("getProgramAccounts") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":[{\"pubkey\":\"So11111111111111111111111111111111111111112\",\"account\":{\"data\":[\"AQID\",\"base64\"],\"lamports\":5}}]}"};
        if (body.find("getSignaturesForAddress") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":[{\"signature\":\"sigA\",\"err\":null,\"slot\":9},{\"signature\":\"sigB\",\"err\":{\"x\":1},\"slot\":8}]}"};
        if (body.find("getAccountInfo") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"context\":{\"slot\":1},\"value\":{\"data\":[\"AQIDBA==\",\"base64\"],\"lamports\":7}}}"};
        if (body.find("\"getSlot\"") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":4242}"};
        if (body.find("getBlockTime") != std::string::npos)
            return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":1762600123}"};
        return {200, "{\"jsonrpc\":\"2.0\",\"id\":1,\"error\":{\"code\":-32601,\"message\":\"nope\"}}"};
    };

    uint64_t rent = 0;
    CHECK(sol.getMinimumBalanceForRentExemption(300, rent) && rent == 2978880, "rent");
    CHECK(lastBody.find("[300]") != std::string::npos, "rent params " + lastBody);

    std::vector<uint8_t> raw;
    CHECK(sol.getAccountData("So11111111111111111111111111111111111111112", raw) && toHex(raw) == "01020304", "getAccountData");

    std::vector<ProgramAccount> accs;
    std::vector<AccountFilter> filters = {AccountFilter::dataSize(300), AccountFilter::memcmp(8, encodeU64LE(5))};
    CHECK(sol.getProgramAccounts("GmHx2yxARZ9ZxQwjceRWMBTXykJo6onZjrkraf4a4zvY", filters, accs) && accs.size() == 1 &&
              toHex(accs[0].data) == "010203" && accs[0].pubkey == "So11111111111111111111111111111111111111112", "getProgramAccounts");
    CHECK(lastBody.find("\"dataSize\":300") != std::string::npos && lastBody.find("\"memcmp\"") != std::string::npos &&
              lastBody.find("\"offset\":8") != std::string::npos, "gPA filters " + lastBody);

    std::vector<SignatureInfo> sigs;
    CHECK(sol.getSignaturesForAddress("GmHx2yxARZ9ZxQwjceRWMBTXykJo6onZjrkraf4a4zvY", sigs, 5) && sigs.size() == 2 &&
              sigs[0].signature == "sigA" && !sigs[0].failed && sigs[1].failed, "getSignaturesForAddress");

    int64_t t = 0;
    CHECK(sol.getClusterTime(t) && t == 1762600123, "cluster time");

    String resp;
    CHECK(!sol.rpcCall("unknownMethod", "[]", resp), "rpc error detection");
}
#endif

int main(int argc, char **argv) {
    const char *path = argc > 1 ? argv[1] : "vectors.json";
    std::ifstream f(path);
    if (!f) { printf("cannot open %s\n", path); return 2; }
    std::stringstream ss; ss << f.rdbuf();
    DynamicJsonDocument doc(1 << 22);
    if (deserializeJson(doc, ss.str())) { printf("bad vectors json\n"); return 2; }

    Infratic sol("https://mock.rpc");
#ifdef INFRATIC_VERSION
    sol.setLogLevel(INFRATIC_LOG_NONE);
    testOnCurve(doc["onCurve"]);
    testEncoders();
    testRpcHelpers(sol);
#endif
    testPda(sol, doc["pda"]);
    testTx(doc["tx"]);
    testSendSol(sol, doc["sendSol"]);
    testEscrowDecode(sol, doc["escrow"]);
#ifdef INFRATIC_VERSION
    testEscrowCreate(sol, doc["escrowCreate"]);
    testSpl(sol, doc["spl"]);
    testComputeBudget(sol, doc["computeBudget"]);
    testNonce(sol, doc["nonce"]);
#endif

    printf("\n%-14s %6s %6s\n", "group", "pass", "fail");
    for (auto &g : g_groups) printf("%-14s %6d %6d\n", g.first.c_str(), g.second.first, g.second.second);
    printf("\nTOTAL pass=%d fail=%d\n", g_pass, g_fail);
    return g_fail ? 1 : 0;
}
